public static class CatalogQ {
 public static readonly CatalogDataQ Data=JsonSerializer.Deserialize<CatalogDataQ>(File.ReadAllText(Path.Combine(AppContext.BaseDirectory,"Assets","SystemsQ","catalog.json")))!;
 public static readonly Dictionary<string,ActivityQ> Activities=Data.Activities.ToDictionary(a=>a.Id);
 public static string Item(int id)=>Data.Aliases.GetValueOrDefault(id.ToString(),"sde_"+id);
 public static readonly HashSet<string> Added=Data.Items.Select(i=>i.Id).ToHashSet();
 public static readonly ItemDefinition[] Items=Data.Items.Select(i=>new ItemDefinition(i.Id,i.Name,"Industry source inventory / "+i.Group,"Pinned source industrial item. Inventory and production support does not promote an unsupported fitting or hull role.",Math.Max(.001f,i.Volume),Math.Max(1,i.Price/1000),"" )).Concat(new[]{new ItemDefinition("q_resource_anchor","Resource stabilizer kit","Structures / Resource equipment","Local physical phased resource anchor; source placement and exact field behavior remain open.",10,1500,""),new ItemDefinition("q_entosis","Territorial link kit","Structures / Territorial equipment","Local physical territorial link equipment; source module fitting certification remains open.",10,1000,"")}).ToArray();
 public static bool Restricted(string id)=>Added.Contains(id)||id.StartsWith("q_");
 public static readonly HashSet<int> PiInputs=Data.Schematics.SelectMany(s=>s.Inputs).Select(q=>q.Type).ToHashSet();
 public static readonly HashSet<int> PiOutputs=Data.Schematics.SelectMany(s=>s.Outputs).Select(q=>q.Type).ToHashSet();
 public static readonly int[] PiRaw=PiInputs.Except(PiOutputs).Order().ToArray();
}
