public sealed partial class DemoWorld {
 public StateQ SystemsQ=>Exploration.SystemsQ;
 public void LogQ(string message){SystemsQ.Journal.Add(Now.ToString("u")+" / "+message);if(SystemsQ.Journal.Count>500)SystemsQ.Journal.RemoveAt(0);}
 public int SlotsQ(string kind)=>kind=="reaction"?1+IndustryLevel("Mass Reactions")+IndustryLevel("Advanced Mass Reactions"):IndustrySlots(kind=="manufacturing");
 public int ActiveSlotsQ(string kind){string Group(string k)=>k=="reaction"?"reaction":k=="manufacturing"?"manufacturing":"science";return Industry.Jobs.Count(j=>(j.State is "Active" or "Ready")&&Group(j.Activity==IndustryActivity.Manufacturing?"manufacturing":"science")==Group(kind))+SystemsQ.Jobs.Count(j=>j.Owner=="player"&&(j.State is "Active" or "Paused" or "Ready")&&Group(CatalogQ.Activities[j.Activity].Kind)==Group(kind));}
 public string BuyBlueprintQ(int type){if(CatalogQ.Data.Activities.Any(a=>a.Kind=="invention"&&a.Outputs.Any(o=>o.Type==type)))return "This output blueprint requires invention; no original is stocked by this local vendor.";if(!Docked||!CatalogQ.Data.Activities.Any(a=>a.Blueprint==type)||!LocationService(StationKey44,14)&&!LocationService(StationKey44,15))return "Dock at an industry service with a source blueprint selection.";string key=StationKey44+":bp:"+type;int remaining=SystemsQ.SupplyStock.GetValueOrDefault(key,3);decimal price=Math.Max(100,ItemCatalog.Get(CatalogQ.Item(type)).Price*8);if(remaining<=0||Balance<price)return "Finite blueprint vendor supply or wallet exhausted.";WalletChange(-price,"Blueprint original acquisition");SystemsQ.SupplyStock[key]=remaining-1;SystemsQ.Blueprints.Add(new(){Type=type,Station=StationKey44});return "";}
 public string BuyInputQ(int type,int amount=100){string item=CatalogQ.Item(type);if(!Docked||amount<1||amount>1000||!CatalogQ.Data.Activities.Any(a=>a.Inputs.Any(i=>i.Type==type))&&!CatalogQ.PiRaw.Contains(type)&&!CatalogQ.Data.Mutators.Any(m=>m.Type==type))return "Dock and choose a listed source input or mutator.";string key=StationKey44+":supply:"+type;int stock=SystemsQ.SupplyStock.GetValueOrDefault(key,1000);decimal cost=ItemCatalog.Get(item).Price*amount;if(stock<amount||Balance<cost)return "Finite opening specialist stock or wallet exhausted.";WalletChange(-cost,"Finite specialist inputs");SystemsQ.SupplyStock[key]=stock-amount;Hangar[item]=Hangar.GetValueOrDefault(item)+amount;return "";}
 public QuoteQ QuoteIndustryQ(string activity,string blueprint,int runs=1,string facility="",int target=0){var empty=new Dictionary<string,decimal>();if(!CatalogQ.Activities.TryGetValue(activity,out var a)||SystemsQ.Blueprints.FirstOrDefault(b=>b.Id==blueprint) is not {} bp||a.Blueprint!=bp.Type||bp.Locked!=""||bp.Owner!="player"||bp.Station!=StationKey44||!Docked||runs<1||runs>Math.Min(1000,Math.Max(1,a.MaxRuns)))return new(empty,0,0,runs,"Local unlocked source blueprint and valid run count required.");
  if(!SkillCatalog.VerificationAllV&&a.Skills.Any(s=>!SkillCatalog.ById.ContainsKey(s.typeID)||Skills.Trained(s.typeID)<s.level))return new(empty,0,0,runs,"Source activity skill requirements are unmet.");
  if(a.Kind is "copying" or "research_material" or "research_time"&&(!bp.Original||!LocationService(StationKey44,15)))return new(empty,0,0,runs,"Research/copying requires an original and research service.");
  if(a.Kind=="invention"&&(bp.Original||bp.Runs<runs))return new(empty,0,0,runs,"Invention requires a real blueprint copy with available runs.");
  if(a.Kind=="manufacturing"&&!bp.Original&&bp.Runs<runs)return new(empty,0,0,runs,"Insufficient blueprint copy runs.");
  var f=Production.Facilities.FirstOrDefault(f=>f.Id==facility);if(a.Kind=="reaction"&&(f is not{Kind:"Refinery",Online:true,Destroyed:false}||f.Station!=StationKey44||Current.Security>.4))return new(empty,0,0,runs,"Reactions require an online local refinery in security 0.4 or lower.");
  if(a.Kind=="manufacturing"&&!LocationService(StationKey44,14))return new(empty,0,0,runs,"Manufacturing service unavailable.");
  if(ActiveSlotsQ(a.Kind)>=SlotsQ(a.Kind))return new(empty,0,0,runs,"Shared industry slots occupied.");
  int me=a.Kind=="manufacturing"?bp.ME:0;var inputs=a.Inputs.ToDictionary(i=>CatalogQ.Item(i.Type),i=>Math.Max(runs,decimal.Ceiling(i.Quantity*(decimal)runs*(1-me/100m))));
  double seconds=Math.Max(1,a.Seconds)*(double)runs*(a.Kind=="manufacturing"?1-bp.TE/100d:1)*(1-.04*Math.Min(5,IndustryLevel("Industry")));
  if(a.Kind is "research_material" or "research_time"){int current=a.Kind=="research_material"?bp.ME:bp.TE/2;int next=target;if(next<=current||next>10)return new(empty,0,0,runs,"Select a higher research level through ten.");seconds=a.Seconds*(IndustryCatalog37.ResearchTotals[next]-IndustryCatalog37.ResearchTotals[current])/105;}
  if(a.Kind=="copying"){if(target<1||target>a.MaxRuns)return new(empty,0,0,runs,"Select a copy run count within the source maximum.");seconds*=target;}
  if(a.Kind=="reaction")inputs["fuel"]=inputs.GetValueOrDefault("fuel")+runs;decimal estimated=a.Outputs.Sum(o=>ItemCatalog.Get(CatalogQ.Item(o.Type)).Price*o.Quantity*runs);decimal fee=Math.Max(1,Math.Round(Math.Max(estimated,inputs.Sum(i=>ItemCatalog.Get(i.Key).Price*i.Value))*.04m,2));string error=inputs.Any(i=>Hangar.GetValueOrDefault(i.Key)<i.Value)?"Missing source materials.":Balance<fee?"Installation wallet too small.":"";return new(inputs,seconds,fee,runs,error);
 }
 public string InstallIndustryQ(string activity,string blueprint,int runs=1,string facility="",int target=0){var quote=QuoteIndustryQ(activity,blueprint,runs,facility,target);if(quote.Error!="")return quote.Error;var a=CatalogQ.Activities[activity];var bp=SystemsQ.Blueprints.First(b=>b.Id==blueprint);var j=new JobQ{Activity=activity,Blueprint=bp.Id,Station=StationKey44,Facility=facility,Runs=runs,Target=target,Started=Now,Last=Now,Finish=Now.AddSeconds(quote.Seconds),Fee=quote.Fee,Inputs=new(quote.Inputs),FuelLeft=a.Kind=="reaction"?runs:0};foreach(var i in quote.Inputs)ChangeStack(i.Key,true,-i.Value);WalletChange(-quote.Fee,"Industry installation");bp.Locked=j.Id;if(!bp.Original&&a.Kind is "invention" or "manufacturing")bp.Runs-=runs;
  if(a.Kind=="invention"){foreach(var output in a.Outputs){int copies=0;for(int i=0;i<runs;i++)if(RollProductionE()<output.Chance)copies++;if(copies>0)j.Copies[output.Type]=copies;}j.Success=j.Copies.Count>0;}
  else if(a.Kind is "manufacturing" or "reaction")foreach(var o in a.Outputs)j.Outputs[CatalogQ.Item(o.Type)]=o.Quantity*runs;
  SystemsQ.Jobs.Add(j);LogQ("Installed "+a.Name+" / "+a.Kind+" / "+runs);return "";
 }
 public void TickIndustryQ(){foreach(var j in SystemsQ.Jobs.Where(j=>j.State is "Active" or "Paused")){var f=j.Facility==""?null:Production.Facilities.FirstOrDefault(f=>f.Id==j.Facility);if(j.Facility!=""&&(f==null||f.Destroyed)){j.State="Lost";UnlockIndustryQ(j);continue;}if(j.Facility!=""&&!f!.Online){if(j.State=="Active")j.State="Paused";j.Finish=j.Finish.AddSeconds(Math.Max(0,(Now-j.Last).TotalSeconds));j.Last=Now;continue;}if(j.State=="Paused")j.Finish=j.Finish.AddSeconds(Math.Max(0,(Now-j.Last).TotalSeconds));j.State="Active";j.Last=Now;if(j.Finish<=Now)j.State="Ready";}}
 void UnlockIndustryQ(JobQ j){var bp=SystemsQ.Blueprints.FirstOrDefault(b=>b.Id==j.Blueprint);if(bp?.Locked==j.Id)bp.Locked="";}
 public string DeliverIndustryQ(string id){TickIndustryQ();var j=SystemsQ.Jobs.FirstOrDefault(j=>j.Id==id);if(j is not {State:"Ready",Owner:"player"}||!Docked||j.Station!=StationKey44)return "Dock at a ready job's output station.";var a=CatalogQ.Activities[j.Activity];var bp=SystemsQ.Blueprints.First(b=>b.Id==j.Blueprint);foreach(var i in j.Outputs)ChangeStack(i.Key,true,i.Value);foreach(var c in j.Copies)for(int n=0;n<c.Value;n++)SystemsQ.Blueprints.Add(new(){Type=c.Key,Station=j.Station,Original=false,Runs=Math.Max(1,a.Outputs.First(o=>o.Type==c.Key).Quantity),ME=2,TE=4});if(a.Kind=="copying")for(int n=0;n<j.Runs;n++)SystemsQ.Blueprints.Add(new(){Type=bp.Type,Station=bp.Station,Original=false,Runs=j.Target,ME=bp.ME,TE=bp.TE});if(a.Kind=="research_material")bp.ME=j.Target;if(a.Kind=="research_time")bp.TE=j.Target*2;UnlockIndustryQ(j);j.State="Delivered";j.FuelLeft=0;LogQ("Delivered once / "+j.Id);return "";}
 public string CancelIndustryQ(string id){var j=SystemsQ.Jobs.FirstOrDefault(j=>j.Id==id&&j.Owner=="player");if(j==null||j.State is not("Active" or "Paused" or "Ready"))return "Job cannot be cancelled.";j.State="Cancelled";j.Outputs.Clear();j.Copies.Clear();j.FuelLeft=0;UnlockIndustryQ(j);LogQ("Cancelled / inputs and fees consumed / "+id);return "";}
 public ContractD? CorporateContractQ(ContractKindD kind,Dictionary<string,decimal> items,string destination,decimal price,decimal reward,decimal collateral){if(CorporationG==null||!HasRoleG("Accountant"))return null;var c=CreateContractD(kind,"Corporate logistics",items,destination,price,reward,collateral,audience:"Corporation",recipient:CorporationG.Id);if(c!=null)c.CorporationQ=true;return c;}
 public void TickSystemsQ(double seconds){TickIndustryQ();TickPlanetaryQ();TickMiningQ(seconds);TickLegalQ(seconds);TickTerritoryQ(seconds);TickEconomyQ();}
}
